#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

#define MAXN 100005

typedef struct {
    long long key;
    uint32_t priority;
    int size;
    int left, right;
} Node;

Node tree[MAXN];
int node_count = 0;

static inline uint32_t xorshift32(void) {
    static uint32_t x = 2463534242U;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    return x;
}

static inline void update(int t) {
    if (t) {
        tree[t].size = 1 + (tree[t].left ? tree[tree[t].left].size : 0) + 
                           (tree[t].right ? tree[tree[t].right].size : 0);
    }
}

void split(int t, long long key, int *l, int *r) {
    if (!t) {
        *l = *r = 0;
        return;
    }
    if (tree[t].key <= key) {
        split(tree[t].right, key, &tree[t].right, r);
        *l = t;
    } else {
        split(tree[t].left, key, l, &tree[t].left);
        *r = t;
    }
    update(t);
}

int merge(int l, int r) {
    if (!l || !r) return l ? l : r;
    if (tree[l].priority > tree[r].priority) {
        tree[l].right = merge(tree[l].right, r);
        update(l);
        return l;
    } else {
        tree[r].left = merge(l, tree[r].left);
        update(r);
        return r;
    }
}

int count_le(int t, long long key) {
    int ans = 0;
    while (t) {
        if (tree[t].key <= key) {
            ans += 1 + (tree[t].left ? tree[tree[t].left].size : 0);
            t = tree[t].right;
        } else {
            t = tree[t].left;
        }
    }
    return ans;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int root = 0;
    long long last_p = 0;

    for (int i = 0; i < n; i++) {
        long long x, y;
        scanf("%lld %lld", &x, &y);

        long long xr = x + last_p;
        long long yr = y + last_p;

        long long dist_sq = xr * xr + yr * yr;

        int p = count_le(root, dist_sq);
        printf("%d\n", p);
        last_p = p;

        node_count++;
        tree[node_count].key = dist_sq;
        tree[node_count].priority = xorshift32();
        tree[node_count].size = 1;
        tree[node_count].left = 0;
        tree[node_count].right = 0;

        int l, r;
        split(root, dist_sq, &l, &r);
        root = merge(merge(l, node_count), r);
    }

    return 0;
}
